-- Server-only (docs/ADMIN.md): RLS on and no grants on the audit log. profiles.banned_at / ban_reason are not in the
-- learner's UPDATE column grant (0005), so only the server can ban.
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON public.admin_audit FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON public.admin_audit FROM authenticated';
  END IF;
END $$;
